                if(guide.buffer==null||guide.node!=node)continue;var block=guide.block;block.SetBuffer("_GuidePoints",guide.buffer);block.SetVector("_GuideOrigin",(model.Current[body.parent].position+guide.reference-observer).Float);block.SetMatrix("_GuideVP",vp);block.SetVector("_GuideScreen",new Vector4(camera.pixelWidth,camera.pixelHeight,Math.Min(1,camera.nearClipPlane),BodyGuideSamples));var colour=body.kind==CelestialKind.Star?new Color(1,.7f,.25f,.22f):body.kind==CelestialKind.Moon?new Color(.75f,.55f,1,.35f):new Color(.25f,.65f,1,node==approachTarget?.6f:.25f);block.SetColor("_GuideColour",colour);cmd.DrawProcedural(Matrix4x4.identity,bodyGuideMaterial,0,MeshTopology.Triangles,(BodyGuideSamples-1)*4*6,1,block);
            }
