            bool Project(Double3 point,out Vector2 screen,bool requireInside=true){var d=point-observer;var p=camera.WorldToViewportPoint(camera.transform.position+d.Float.normalized*1000);float width=pilotUi.Root.resolvedStyle.width,height=pilotUi.Root.resolvedStyle.height;screen=new Vector2(p.x*width,(1-p.y)*height);return p.z>0&&(!requireInside||p.x>.02f&&p.x<.95f&&p.y>.08f&&p.y<.92f);}
